/* Original practice material. Each level contains exactly five questions. */
const q = (prompt, options, answer, explanation) => ({ prompt, options, answer, explanation });
const CURRICULUM = {
  6: {
    theme: 'mint', name: 'Build your foundation', description: 'Big discoveries start with the basics. Get friendly with numbers, shapes, and everything in between.', topics: 'Fractions, percentages & shapes',
    levels: [
      {title:'Fractions & decimals',tagline:'Small pieces. A bigger picture.',intro:'Fractions and decimals are two ways to describe parts of a whole. Learning to move between them makes everyday calculations easier.',rules:[['Add like a pro','Give fractions the same denominator before adding or subtracting. Only the numerators change.'],['Find a fraction of an amount','Divide by the denominator, then multiply by the numerator.'],['Connect the dots','Divide the numerator by the denominator to turn a fraction into a decimal. For example, 3 ÷ 4 = 0.75.']],example:{problem:'What is 1/2 + 1/4?',steps:['Rewrite 1/2 with a denominator of 4: 1/2 = 2/4.','Add the numerators: 2/4 + 1/4 = 3/4.'],answer:'3/4'},questions:[q('What is 1/2 + 1/4?',['2/6','3/4','1/6','1/4'],1,'Rewrite 1/2 as 2/4, then add: 2/4 + 1/4 = 3/4.'),q('Which fraction is equal to 0.6?',['1/6','6/100','3/5','2/3'],2,'0.6 = 6/10. Divide the numerator and denominator by 2 to get 3/5.'),q('What is 3/4 of 20?',['5','10','12','15'],3,'Divide 20 by 4 to get 5, then multiply by 3: 5 × 3 = 15.'),q('What is 0.35 + 0.4?',['0.39','0.75','0.7','0.45'],1,'Line up the decimal points: 0.35 + 0.40 = 0.75.'),q('What is 2/3 − 1/6?',['1/3','1/6','1/2','3/2'],2,'Use sixths: 2/3 = 4/6, so 4/6 − 1/6 = 3/6 = 1/2.')]},
      {title:'Ratios & percentages',tagline:'Put numbers in perspective.',intro:'A ratio compares amounts. A percentage compares an amount to 100. Both help us describe how quantities are related.',rules:[['Read a ratio','A ratio of 2 : 3 means 2 parts of one quantity for every 3 parts of the other. There are 5 parts altogether.'],['Find a percentage','To find 25% of an amount, multiply by 25/100, or simply divide by 4.'],['Work out a discount','Find the discount first, then subtract it from the original price.']],example:{problem:'Red and blue counters are in the ratio 2 : 3. There are 25 counters. How many are red?',steps:['There are 2 + 3 = 5 equal parts. Each part has 25 ÷ 5 = 5 counters.','Red takes 2 parts, so 2 × 5 = 10.'],answer:'10 red counters'},questions:[q('Red : blue counters = 2 : 3. There are 25 counters altogether. How many are red?',['5','10','15','20'],1,'There are 5 parts in total. Each part is 25 ÷ 5 = 5 counters. Red has 2 parts: 2 × 5 = 10.'),q('What is 25% of 80?',['20','25','40','60'],0,'25% is one quarter. 80 ÷ 4 = 20.'),q('What percentage of 12 is 3?',['3%','12%','25%','36%'],2,'3 ÷ 12 = 0.25. Multiply by 100 to get 25%.'),q('A $60 bag has a 10% discount. What is its sale price?',['$6','$50','$54','$66'],2,'10% of $60 is $6. Subtract the discount: $60 − $6 = $54.'),q('Flour : sugar = 4 : 1. If you use 300 g of flour, how much sugar is needed?',['50 g','75 g','100 g','1200 g'],1,'4 parts of flour weigh 300 g, so one part is 300 ÷ 4 = 75 g. Sugar is one part.')]},
      {title:'Shapes & measurement',tagline:'Think outside the square.',intro:'Measurement helps us describe the space around us. Perimeter measures the edge, area measures a surface, and volume measures the space inside a solid.',rules:[['Around and inside','A rectangle has perimeter 2 × (length + width) and area length × width.'],['Half a rectangle','The area of a triangle is 1/2 × base × perpendicular height.'],['Angles and volume','Angles on a straight line add to 180°. A cube with side s has volume s × s × s.']],example:{problem:'Find the area of a triangle with base 10 cm and height 6 cm.',steps:['Use area = 1/2 × base × perpendicular height.','Substitute the measurements: 1/2 × 10 × 6 = 30.'],answer:'30 cm²'},questions:[q('A rectangle is 8 cm long and 5 cm wide. What is its area?',['13 cm²','26 cm²','40 cm²','80 cm²'],2,'Area = length × width = 8 × 5 = 40 cm².'),q('A triangle has base 10 cm and perpendicular height 6 cm. What is its area?',['16 cm²','30 cm²','60 cm²','32 cm²'],1,'Triangle area = 1/2 × 10 × 6 = 30 cm².'),q('Two adjacent angles form a straight line. One is 125°. What is the other?',['35°','55°','65°','125°'],1,'Angles on a straight line add to 180°. 180 − 125 = 55°.'),q('A cube has side length 4 cm. What is its volume?',['12 cm³','16 cm³','48 cm³','64 cm³'],3,'Cube volume = side × side × side = 4 × 4 × 4 = 64 cm³.'),q('A rectangle is 7 m long and 3 m wide. What is its perimeter?',['10 m','20 m','21 m','42 m'],1,'Add all four sides: 7 + 3 + 7 + 3 = 20 m.')]}
    ]
  },
  7: {theme:'peach',name:'Find your rhythm',description:'Connect what you know to something new. Explore integers, unlock algebra, and make sense of chance.',topics:'Integers, algebra & probability',levels:[
    {title:'Integers & expressions',tagline:'Meet the language of maths.',intro:'Integers include positive numbers, negative numbers, and zero. Algebra uses letters to represent values and helps us describe patterns.',rules:[['Move along the number line','Adding a positive number moves right. Adding a negative number moves left. A negative times a positive is negative.'],['Collect like terms','Terms with the same letter and power can be combined: 3x + 2x = 5x.'],['Substitute and expand','Replace a letter with its value to evaluate. To expand brackets, multiply every term inside.']],example:{problem:'Expand 3(x + 4).',steps:['Multiply 3 by x to get 3x.','Multiply 3 by 4 to get 12, then add the terms.'],answer:'3x + 12'},questions:[q('What is −7 + 12?',['−19','−5','5','19'],2,'Start at −7 and move 12 steps right along the number line. You reach 5.'),q('What is −4 × 6?',['−24','−10','10','24'],0,'A negative times a positive is negative. Since 4 × 6 = 24, the answer is −24.'),q('Simplify 3x + 2x.',['5x','5x²','6x','x'],0,'Both terms have x, so add the coefficients: 3 + 2 = 5. The answer is 5x.'),q('If a = 4, what is 2a + 5?',['9','11','13','18'],2,'Replace a with 4: 2 × 4 + 5 = 8 + 5 = 13.'),q('Expand 3(x + 4).',['3x + 4','x + 12','7x','3x + 12'],3,'Multiply both terms in the brackets by 3: 3 × x + 3 × 4 = 3x + 12.')]},
    {title:'Equations & proportion',tagline:'Keep both sides in balance.',intro:'An equation says two expressions are equal. Solve it by undoing operations, keeping both sides balanced. Proportion connects quantities that scale together.',rules:[['Undo in reverse','For 3x + 5 = 20, subtract 5 first, then divide by 3. Do the same thing to both sides.'],['Share using a ratio','Add the ratio parts, divide the total by that sum, then multiply by the parts you need.'],['Find the unit rate','Divide to find the cost of one item, then multiply by the new number of items.']],example:{problem:'Solve 3x + 5 = 20.',steps:['Subtract 5 from both sides: 3x = 15.','Divide both sides by 3: x = 5. Check: 3 × 5 + 5 = 20.'],answer:'x = 5'},questions:[q('Solve 3x + 5 = 20.',['x = 3','x = 5','x = 8','x = 15'],1,'Subtract 5 to get 3x = 15, then divide by 3 to get x = 5.'),q('Solve 4x = 28.',['x = 4','x = 6','x = 7','x = 24'],2,'Divide both sides by 4: x = 28 ÷ 4 = 7.'),q('Share 40 counters in the ratio 3 : 5. How many are in the first share?',['8','15','24','25'],1,'There are 8 parts. Each part is 40 ÷ 8 = 5. The first share has 3 × 5 = 15 counters.'),q('Six identical notebooks cost $18. At the same rate, what do ten cost?',['$24','$28','$30','$36'],2,'One notebook costs $18 ÷ 6 = $3. Ten cost 10 × $3 = $30.'),q('Solve x/4 − 2 = 3.',['x = 4','x = 5','x = 12','x = 20'],3,'Add 2 to get x/4 = 5, then multiply by 4 to get x = 20.')]},
    {title:'Angles & probability',tagline:'Look at things from a new angle.',intro:'Angle rules help us find missing measurements. Probability tells us how likely an event is, from impossible (0) to certain (1).',rules:[['The triangle rule','The interior angles in every triangle add to 180°. Vertically opposite angles are equal.'],['Count the outcomes','For equally likely outcomes, probability = favourable outcomes ÷ total outcomes.'],['Circle basics','A radius runs from the centre to the circle. A diameter goes all the way across through the centre, so diameter = 2 × radius.']],example:{problem:'A triangle has angles 45° and 65°. Find its third angle.',steps:['Add the known angles: 45 + 65 = 110°.','Subtract from 180°: 180 − 110 = 70°.'],answer:'70°'},questions:[q('A triangle has angles 45° and 65°. What is the third angle?',['60°','65°','70°','110°'],2,'The angles total 180°. So the missing angle is 180 − 45 − 65 = 70°.'),q('What is the probability of rolling a 4 on a fair six-sided die?',['1/2','1/4','1/6','4/6'],2,'There is one favourable face out of six equally likely faces, giving 1/6.'),q('A bag contains 3 red and 2 blue counters. One is chosen at random. What is P(blue)?',['2/3','2/5','3/5','1/5'],1,'There are 5 counters altogether, and 2 are blue. P(blue) = 2/5.'),q('Two straight lines intersect. One angle is 65°. What is its vertically opposite angle?',['25°','65°','115°','180°'],1,'Vertically opposite angles are equal, so the opposite angle is also 65°.'),q('A circle has radius 7 cm. What is its diameter?',['3.5 cm','7 cm','14 cm','49 cm'],2,'Diameter = 2 × radius = 2 × 7 = 14 cm.')]}
  ]},
  8: {theme:'lavender',name:'Make new connections',description:'Spot the patterns behind the numbers. Explore powers, straight lines, and the geometry of the real world.',topics:'Powers, linear graphs & geometry',levels:[
    {title:'Powers & roots',tagline:'Give your numbers a superpower.',intro:'A power is a shortcut for repeated multiplication. Roots undo powers. Scientific notation makes very large or small numbers easier to read.',rules:[['Read the exponent','2⁴ means 2 × 2 × 2 × 2 = 16. Any non-zero number to the power of zero is 1.'],['Use index laws','When multiplying powers with the same base, add the exponents: 3² × 3³ = 3⁵.'],['Small numbers, neatly written','Scientific notation has the form a × 10ⁿ, where 1 ≤ a < 10. Negative exponents represent small numbers.']],example:{problem:'Write 0.00042 in scientific notation.',steps:['Move the decimal point 4 places right to get 4.2.','Use 10⁻⁴ to account for the move.'],answer:'4.2 × 10⁻⁴'},questions:[q('What is 2⁴?',['6','8','16','24'],2,'2⁴ = 2 × 2 × 2 × 2 = 16.'),q('What is √81?',['8','9','18','40.5'],1,'The square root is the non-negative number whose square is 81. Since 9 × 9 = 81, √81 = 9.'),q('Simplify 3² × 3³.',['3⁶','6⁵','3⁵','9⁵'],2,'The bases are the same, so add the exponents: 2 + 3 = 5. The result is 3⁵.'),q('What is 5⁰?',['0','1','5','10'],1,'Every non-zero number raised to the power of zero equals 1.'),q('Write 0.00042 in scientific notation.',['4.2 × 10⁴','42 × 10⁻⁴','4.2 × 10⁻³','4.2 × 10⁻⁴'],3,'Move the decimal 4 places to turn 0.00042 into 4.2. Compensate with 10⁻⁴.')]},
    {title:'Linear relationships',tagline:'Follow the pattern. Find the line.',intro:'A linear relationship changes at a constant rate. Its graph is a straight line, often written as y = mx + b.',rules:[['Meet m and b','In y = mx + b, m is the gradient (change in y ÷ change in x), and b is the y-intercept.'],['Find a point','Substitute the x-coordinate into the equation and calculate y.'],['Solve step by step','Undo addition or subtraction first, then undo multiplication or division. Keep both sides balanced.']],example:{problem:'Find y when y = 3x + 2 and x = 4.',steps:['Substitute x = 4: y = 3 × 4 + 2.','Multiply, then add: y = 12 + 2 = 14.'],answer:'y = 14'},questions:[q('Solve 2x − 7 = 9.',['x = 1','x = 4','x = 8','x = 16'],2,'Add 7 to both sides: 2x = 16. Divide by 2: x = 8.'),q('If y = 3x + 2 and x = 4, what is y?',['9','12','14','18'],2,'Substitute x = 4: y = 3 × 4 + 2 = 14.'),q('What is the gradient of the line through (1, 3) and (3, 7)?',['1','2','3','4'],1,'Gradient = change in y ÷ change in x = (7 − 3) ÷ (3 − 1) = 4 ÷ 2 = 2.'),q('What is the y-intercept of y = 2x − 5?',['−5','−2','2','5'],0,'The y-intercept is the value of y when x = 0. Then y = 2 × 0 − 5 = −5.'),q('Which point lies on the line y = 2x + 1?',['(2, 4)','(3, 6)','(2, 5)','(1, 2)'],2,'For x = 2, y = 2 × 2 + 1 = 5. So (2, 5) lies on the line.')]},
    {title:'Geometry & data',tagline:'See the shape of the answer.',intro:'Geometry helps us reason about space. Statistics helps us see what a set of data is telling us. Both turn information into useful patterns.',rules:[['Pythagoras’ theorem','For a right-angled triangle, a² + b² = c², where c is the hypotenuse, opposite the right angle.'],['Find the centre','The mean is the sum divided by the number of values. The median is the middle value after sorting.'],['Circle and spread','Circle area = πr². The range of a data set is its largest value minus its smallest.']],example:{problem:'Find the hypotenuse of a right-angled triangle with shorter sides 3 cm and 4 cm.',steps:['Use c² = 3² + 4² = 9 + 16 = 25.','Take the positive square root: c = √25 = 5.'],answer:'5 cm'},questions:[q('A right-angled triangle has shorter sides 3 cm and 4 cm. Find its hypotenuse.',['5 cm','7 cm','12 cm','25 cm'],0,'By Pythagoras, c² = 3² + 4² = 25, so c = 5 cm.'),q('What is the mean of 4, 6, 8, and 10?',['6','7','8','28'],1,'The sum is 28 and there are 4 values. Mean = 28 ÷ 4 = 7.'),q('What is the median of 2, 4, 7, 9, and 13?',['4','7','9','11'],1,'The data is already in order. The third (middle) value is 7.'),q('A circle has radius 3 cm. What is its exact area?',['3π cm²','6π cm²','9π cm²','18π cm²'],2,'Area = πr² = π × 3² = 9π cm².'),q('What is the range of 5, 8, 3, 12, and 7?',['5','7','9','12'],2,'Largest − smallest = 12 − 3 = 9.')]}
  ]},
  9: {theme:'yellow',name:'Take your thinking further',description:'Ready for your next lightbulb moment? Tackle quadratics, trigonometry, and more confident problem-solving.',topics:'Quadratics, trigonometry & statistics',levels:[
    {title:'Algebra & quadratics',tagline:'More than one way to find x.',intro:'Quadratic expressions include a squared variable. Expanding, factorising, and solving let us look at them in different ways.',rules:[['Expand every pair','For (x + 3)(x + 2), multiply each term in the first bracket by each term in the second. Then collect like terms.'],['Factorise a quadratic','To factorise x² + bx + c, look for two numbers that add to b and multiply to c.'],['Use the zero-product rule','If two factors multiply to zero, at least one factor must be zero. This can give two solutions.']],example:{problem:'Solve (x − 2)(x + 3) = 0.',steps:['Set each factor equal to zero: x − 2 = 0 or x + 3 = 0.','Solve each equation: x = 2 or x = −3.'],answer:'x = 2 or x = −3'},questions:[q('Expand (x + 3)(x + 2).',['x² + 5x + 6','x² + 6','x² + 6x + 5','2x + 5'],0,'Multiply to get x² + 2x + 3x + 6, then combine like terms: x² + 5x + 6.'),q('Factorise x² + 7x + 12.',['(x + 2)(x + 6)','(x + 3)(x + 4)','(x − 3)(x − 4)','(x + 1)(x + 12)'],1,'3 + 4 = 7 and 3 × 4 = 12, so the factors are (x + 3)(x + 4).'),q('Solve (x − 2)(x + 3) = 0.',['x = −2 or 3','x = 2 only','x = 2 or −3','x = −3 only'],2,'Set each factor to zero: x − 2 = 0 gives x = 2; x + 3 = 0 gives x = −3.'),q('Simplify (2x)².',['2x²','4x','4x²','2x'],2,'Square both the coefficient and the variable: (2x)² = 2² × x² = 4x².'),q('Solve x² = 49 over the real numbers.',['x = 7 only','x = −7 only','x = 24.5','x = 7 or −7'],3,'Both 7² and (−7)² equal 49, so x = ±7.')]},
    {title:'Trigonometry & geometry',tagline:'A fresh angle on problem-solving.',intro:'Trigonometry links angles to side lengths in right-angled triangles. Start by labelling the opposite, adjacent, and hypotenuse relative to your chosen angle.',rules:[['Remember SOH CAH TOA','sin θ = opposite/hypotenuse; cos θ = adjacent/hypotenuse; tan θ = opposite/adjacent.'],['Name the sides carefully','The hypotenuse is always opposite the right angle. The opposite and adjacent sides depend on the acute angle you are using.'],['Use the right tool','Pythagoras connects three sides. Trigonometry connects an acute angle with two sides. Use degree mode for these questions.']],example:{problem:'In a right-angled triangle, an angle is 30° and the hypotenuse is 10 cm. Find the opposite side.',steps:['Use sin 30° = opposite/10. Since sin 30° = 1/2, opposite/10 = 1/2.','Multiply by 10: opposite = 5 cm.'],answer:'5 cm'},questions:[q('Which ratio equals sin θ in a right-angled triangle?',['Adjacent / hypotenuse','Opposite / hypotenuse','Opposite / adjacent','Hypotenuse / opposite'],1,'SOH means sine = opposite ÷ hypotenuse.'),q('A right-angled triangle has a 30° angle and hypotenuse 10 cm. Find the side opposite 30°.',['5 cm','8.66 cm','10 cm','20 cm'],0,'sin 30° = 1/2, so opposite = 10 × 1/2 = 5 cm.'),q('A right-angled triangle has opposite side 6 cm and adjacent side 8 cm relative to θ. Find tan θ.',['0.6','0.75','1.25','1.33'],1,'tan θ = opposite ÷ adjacent = 6 ÷ 8 = 0.75.'),q('A right-angled triangle has shorter sides 5 cm and 12 cm. Find the hypotenuse.',['7 cm','13 cm','17 cm','169 cm'],1,'c² = 5² + 12² = 25 + 144 = 169, so c = 13 cm.'),q('Two similar triangles have corresponding side lengths in the ratio 2 : 3. What is their area ratio?',['2 : 3','3 : 2','4 : 6','4 : 9'],3,'Area scales by the square of the length scale factor, so the area ratio is 2² : 3² = 4 : 9.')]},
    {title:'Probability & statistics',tagline:'Turn uncertainty into understanding.',intro:'Probability helps us reason about uncertain outcomes. Statistics helps us compare data and understand the effect of unusual values.',rules:[['Independent events','For independent events, multiply the probabilities to find the chance of both happening. One event does not change the other.'],['Without replacement','When an item is not replaced, update both the favourable count and the total before calculating the next probability.'],['Look beyond the average','An outlier can strongly affect the mean. The median is often less affected by an extreme value.']],example:{problem:'Two fair coins are tossed. What is the probability that both show heads?',steps:['Each coin has P(heads) = 1/2. The tosses are independent.','Multiply: 1/2 × 1/2 = 1/4.'],answer:'1/4'},questions:[q('Two fair coins are tossed. What is the probability of two heads?',['1/2','1/3','1/4','3/4'],2,'The tosses are independent: P(HH) = 1/2 × 1/2 = 1/4.'),q('A fair six-sided die is rolled. What is the probability of a number greater than 4?',['1/6','1/3','1/2','2/3'],1,'The favourable outcomes are 5 and 6: 2 out of 6, which simplifies to 1/3.'),q('A bag has 3 red and 2 blue counters. Two are drawn without replacement. What is P(both red)?',['9/25','3/10','6/25','1/2'],1,'P(first red) = 3/5. Then 2 red remain among 4 counters, so P(both) = 3/5 × 2/4 = 6/20 = 3/10.'),q('Which measure is usually least affected by a single extreme outlier?',['Mean','Range','Median','Maximum'],2,'The median depends on the middle position, so one extreme value usually has less effect on it than on the mean or range.'),q('What is the mean of 3, 5, 7, 9, and 11?',['5','6','7','9'],2,'Add the values to get 35, then divide by 5: mean = 7.')]}
  ]}
};
